from src.heap_ops import heap_sort, nlargest, nsmallest


def test_heap_sort_basic():
    assert heap_sort([3, 1, 4, 1, 5, 9, 2, 6]) == [1, 1, 2, 3, 4, 5, 6, 9]


def test_heap_sort_empty():
    assert heap_sort([]) == []


def test_nlargest():
    assert nlargest(3, [3, 1, 4, 1, 5, 9, 2, 6]) == [9, 6, 5]


def test_nsmallest():
    assert nsmallest(3, [3, 1, 4, 1, 5, 9, 2, 6]) == [1, 1, 2]


def test_heap_sort_sorted():
    data = [5, 4, 3, 2, 1]
    assert heap_sort(data) == [1, 2, 3, 4, 5]
    assert data == [5, 4, 3, 2, 1]  # original unchanged
